import json,pathlib,datetime,os
p=pathlib.Path('state/publishing.json');s=json.loads(p.read_text());s['lastSuccessfulDeployment']={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'commit':os.environ['GITHUB_SHA'],'runUrl':f'https://github.com/{os.environ["GITHUB_REPOSITORY"]}/actions/runs/{os.environ["GITHUB_RUN_ID"]}','url':os.environ['PAGE_URL']};s['completedIssues']=[json.loads(i.read_text())['id'] for i in sorted(pathlib.Path('content/issues').glob('*.json'))];p.write_text(json.dumps(s,indent=2)+'\n')
